CREATE TABLE en1994_document (id INTEGER PRIMARY KEY CHECK(id=1),annex TEXT NOT NULL CHECK(annex IN ('En','De')),structure_kind TEXT NOT NULL CHECK(structure_kind IN ('building','bridge')),steel_f_y_pa REAL,fire_rating TEXT NOT NULL CHECK(fire_rating IN ('unrated','r30','r60','r90','r120')),insulation_thickness_m REAL,fatigue_detail TEXT NOT NULL CHECK(fatigue_detail IN ('studWelded','shearConnector','reinforcement','flangeButtWeld')),reliability_class TEXT NOT NULL CHECK(reliability_class IN ('RC1','RC2','RC3')),steel_f_y_pa_ieee754_bits INTEGER NOT NULL,steel_f_y_pa_ieee754_class TEXT NOT NULL,insulation_thickness_m_ieee754_bits INTEGER NOT NULL,insulation_thickness_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_beam (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1994_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,span_m REAL,spacing_m REAL,support TEXT NOT NULL CHECK(support IN ('simplySupported','continuous2Span','endSpan','interiorSpan','cantilever')),construction TEXT NOT NULL CHECK(construction IN ('propped','unpropped')),slab_thickness_m REAL,concrete_f_ck_pa REAL,concrete_e_cm_pa REAL,transverse_as_m2_per_m REAL,ltb_length_m REAL,as_hogging_m2_per_m REAL,bar_spacing_m REAL,wk_limit_m REAL,n_cycles REAL,adjacent_span_m REAL,patch_bearing_length_m REAL,bridge_lanes INTEGER NOT NULL CHECK(bridge_lanes BETWEEN 0 AND 4294967295),cracked_length_fraction REAL,stud_transverse_spacing_m REAL,stud_edge_distance_m REAL,transverse_as_top_m2_per_m REAL,end_plate_width_m REAL,end_plate_height_m REAL,end_zone_length_m REAL,reinforcement_product TEXT NOT NULL CHECK(reinforcement_product IN ('hotRolled','coldWorked')),span_m_ieee754_bits INTEGER NOT NULL,span_m_ieee754_class TEXT NOT NULL,spacing_m_ieee754_bits INTEGER NOT NULL,spacing_m_ieee754_class TEXT NOT NULL,slab_thickness_m_ieee754_bits INTEGER NOT NULL,slab_thickness_m_ieee754_class TEXT NOT NULL,concrete_f_ck_pa_ieee754_bits INTEGER NOT NULL,concrete_f_ck_pa_ieee754_class TEXT NOT NULL,concrete_e_cm_pa_ieee754_bits INTEGER NOT NULL,concrete_e_cm_pa_ieee754_class TEXT NOT NULL,transverse_as_m2_per_m_ieee754_bits INTEGER NOT NULL,transverse_as_m2_per_m_ieee754_class TEXT NOT NULL,ltb_length_m_ieee754_bits INTEGER NOT NULL,ltb_length_m_ieee754_class TEXT NOT NULL,as_hogging_m2_per_m_ieee754_bits INTEGER NOT NULL,as_hogging_m2_per_m_ieee754_class TEXT NOT NULL,bar_spacing_m_ieee754_bits INTEGER NOT NULL,bar_spacing_m_ieee754_class TEXT NOT NULL,wk_limit_m_ieee754_bits INTEGER NOT NULL,wk_limit_m_ieee754_class TEXT NOT NULL,n_cycles_ieee754_bits INTEGER NOT NULL,n_cycles_ieee754_class TEXT NOT NULL,adjacent_span_m_ieee754_bits INTEGER NOT NULL,adjacent_span_m_ieee754_class TEXT NOT NULL,patch_bearing_length_m_ieee754_bits INTEGER NOT NULL,patch_bearing_length_m_ieee754_class TEXT NOT NULL,cracked_length_fraction_ieee754_bits INTEGER NOT NULL,cracked_length_fraction_ieee754_class TEXT NOT NULL,stud_transverse_spacing_m_ieee754_bits INTEGER NOT NULL,stud_transverse_spacing_m_ieee754_class TEXT NOT NULL,stud_edge_distance_m_ieee754_bits INTEGER NOT NULL,stud_edge_distance_m_ieee754_class TEXT NOT NULL,transverse_as_top_m2_per_m_ieee754_bits INTEGER NOT NULL,transverse_as_top_m2_per_m_ieee754_class TEXT NOT NULL,end_plate_width_m_ieee754_bits INTEGER NOT NULL,end_plate_width_m_ieee754_class TEXT NOT NULL,end_plate_height_m_ieee754_bits INTEGER NOT NULL,end_plate_height_m_ieee754_class TEXT NOT NULL,end_zone_length_m_ieee754_bits INTEGER NOT NULL,end_zone_length_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_beam_steel (id INTEGER PRIMARY KEY,beam_id INTEGER NOT NULL REFERENCES en1994_beam(id) CHECK(beam_id=id),designation TEXT NOT NULL,height_m REAL,width_m REAL,tw_m REAL,tf_m REAL,a_m2 REAL,w_pl_y_m3 REAL,i_y_m4 REAL,a_v_m2 REAL,r_m REAL,height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,width_m_ieee754_bits INTEGER NOT NULL,width_m_ieee754_class TEXT NOT NULL,tw_m_ieee754_bits INTEGER NOT NULL,tw_m_ieee754_class TEXT NOT NULL,tf_m_ieee754_bits INTEGER NOT NULL,tf_m_ieee754_class TEXT NOT NULL,a_m2_ieee754_bits INTEGER NOT NULL,a_m2_ieee754_class TEXT NOT NULL,w_pl_y_m3_ieee754_bits INTEGER NOT NULL,w_pl_y_m3_ieee754_class TEXT NOT NULL,i_y_m4_ieee754_bits INTEGER NOT NULL,i_y_m4_ieee754_class TEXT NOT NULL,a_v_m2_ieee754_bits INTEGER NOT NULL,a_v_m2_ieee754_class TEXT NOT NULL,r_m_ieee754_bits INTEGER NOT NULL,r_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_beam_sheeting (id INTEGER PRIMARY KEY,beam_id INTEGER NOT NULL REFERENCES en1994_beam(id) CHECK(beam_id=id),profile TEXT NOT NULL CHECK(profile IN ('trapezoidal','reEntrant')),height_m REAL,rib_width_m REAL,thickness_m REAL,ribs_parallel_to_beam INTEGER NOT NULL CHECK(ribs_parallel_to_beam IN (0,1)),height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,rib_width_m_ieee754_bits INTEGER NOT NULL,rib_width_m_ieee754_class TEXT NOT NULL,thickness_m_ieee754_bits INTEGER NOT NULL,thickness_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_beam_action (id INTEGER PRIMARY KEY,beam_id INTEGER NOT NULL REFERENCES en1994_beam(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('permanent','imposed','snow','wind','construction','fatigue')),category TEXT NOT NULL,stage TEXT NOT NULL CHECK(stage IN ('construction','composite','any')),q_area_pa REAL,f_k_n REAL,delta_sigma_k_pa REAL,delta_tau_k_pa REAL,x_m REAL,q_area_pa_ieee754_bits INTEGER NOT NULL,q_area_pa_ieee754_class TEXT NOT NULL,f_k_n_ieee754_bits INTEGER NOT NULL,f_k_n_ieee754_class TEXT NOT NULL,delta_sigma_k_pa_ieee754_bits INTEGER NOT NULL,delta_sigma_k_pa_ieee754_class TEXT NOT NULL,delta_tau_k_pa_ieee754_bits INTEGER NOT NULL,delta_tau_k_pa_ieee754_class TEXT NOT NULL,x_m_ieee754_bits INTEGER NOT NULL,x_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_column (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1994_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('encased','concreteFilled','partiallyEncased')),length_m REAL,outer_size_m REAL,wall_thickness_m REAL,steel_a_m2 REAL,steel_f_y_pa REAL,concrete_a_m2 REAL,concrete_f_ck_pa REAL,reinforcement_as_m2 REAL,reinforcement_f_yk_pa REAL,i_m4 REAL,buckling_curve TEXT NOT NULL CHECK(buckling_curve IN ('a','b','c','d')),introduced_force_n REAL,section_height_m REAL,section_width_m REAL,section_tw_m REAL,section_tf_m REAL,rebar_cover_m REAL,reinforcement_product TEXT NOT NULL CHECK(reinforcement_product IN ('hotRolled','coldWorked')),length_m_ieee754_bits INTEGER NOT NULL,length_m_ieee754_class TEXT NOT NULL,outer_size_m_ieee754_bits INTEGER NOT NULL,outer_size_m_ieee754_class TEXT NOT NULL,wall_thickness_m_ieee754_bits INTEGER NOT NULL,wall_thickness_m_ieee754_class TEXT NOT NULL,steel_a_m2_ieee754_bits INTEGER NOT NULL,steel_a_m2_ieee754_class TEXT NOT NULL,steel_f_y_pa_ieee754_bits INTEGER NOT NULL,steel_f_y_pa_ieee754_class TEXT NOT NULL,concrete_a_m2_ieee754_bits INTEGER NOT NULL,concrete_a_m2_ieee754_class TEXT NOT NULL,concrete_f_ck_pa_ieee754_bits INTEGER NOT NULL,concrete_f_ck_pa_ieee754_class TEXT NOT NULL,reinforcement_as_m2_ieee754_bits INTEGER NOT NULL,reinforcement_as_m2_ieee754_class TEXT NOT NULL,reinforcement_f_yk_pa_ieee754_bits INTEGER NOT NULL,reinforcement_f_yk_pa_ieee754_class TEXT NOT NULL,i_m4_ieee754_bits INTEGER NOT NULL,i_m4_ieee754_class TEXT NOT NULL,introduced_force_n_ieee754_bits INTEGER NOT NULL,introduced_force_n_ieee754_class TEXT NOT NULL,section_height_m_ieee754_bits INTEGER NOT NULL,section_height_m_ieee754_class TEXT NOT NULL,section_width_m_ieee754_bits INTEGER NOT NULL,section_width_m_ieee754_class TEXT NOT NULL,section_tw_m_ieee754_bits INTEGER NOT NULL,section_tw_m_ieee754_class TEXT NOT NULL,section_tf_m_ieee754_bits INTEGER NOT NULL,section_tf_m_ieee754_class TEXT NOT NULL,rebar_cover_m_ieee754_bits INTEGER NOT NULL,rebar_cover_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_column_action (id INTEGER PRIMARY KEY,column_id INTEGER NOT NULL REFERENCES en1994_column(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,kind TEXT NOT NULL,category TEXT NOT NULL,stage TEXT NOT NULL,n_k_n REAL,m_k_nm REAL,n_k_n_ieee754_bits INTEGER NOT NULL,n_k_n_ieee754_class TEXT NOT NULL,m_k_nm_ieee754_bits INTEGER NOT NULL,m_k_nm_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_slab (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1994_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,span_m REAL,support TEXT NOT NULL CHECK(support IN ('simplySupported','continuous2Span','endSpan','interiorSpan','cantilever')),concrete_thickness_m REAL,f_ck_pa REAL,m_factor REAL,k_factor REAL,as_m2_per_m REAL,span_m_ieee754_bits INTEGER NOT NULL,span_m_ieee754_class TEXT NOT NULL,concrete_thickness_m_ieee754_bits INTEGER NOT NULL,concrete_thickness_m_ieee754_class TEXT NOT NULL,f_ck_pa_ieee754_bits INTEGER NOT NULL,f_ck_pa_ieee754_class TEXT NOT NULL,m_factor_ieee754_bits INTEGER NOT NULL,m_factor_ieee754_class TEXT NOT NULL,k_factor_ieee754_bits INTEGER NOT NULL,k_factor_ieee754_class TEXT NOT NULL,as_m2_per_m_ieee754_bits INTEGER NOT NULL,as_m2_per_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_slab_sheeting (id INTEGER PRIMARY KEY,slab_id INTEGER NOT NULL REFERENCES en1994_slab(id) CHECK(slab_id=id),profile TEXT NOT NULL,height_m REAL,rib_width_m REAL,thickness_m REAL,ribs_parallel_to_beam INTEGER NOT NULL CHECK(ribs_parallel_to_beam IN (0,1)),height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,rib_width_m_ieee754_bits INTEGER NOT NULL,rib_width_m_ieee754_class TEXT NOT NULL,thickness_m_ieee754_bits INTEGER NOT NULL,thickness_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_slab_action (id INTEGER PRIMARY KEY,slab_id INTEGER NOT NULL REFERENCES en1994_slab(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('permanent','imposed','snow','wind','construction','fatigue')),category TEXT NOT NULL,stage TEXT NOT NULL CHECK(stage IN ('construction','composite','any')),q_area_pa REAL,f_k_n REAL,delta_sigma_k_pa REAL,delta_tau_k_pa REAL,x_m REAL,y_m REAL,q_area_pa_ieee754_bits INTEGER NOT NULL,q_area_pa_ieee754_class TEXT NOT NULL,f_k_n_ieee754_bits INTEGER NOT NULL,f_k_n_ieee754_class TEXT NOT NULL,delta_sigma_k_pa_ieee754_bits INTEGER NOT NULL,delta_sigma_k_pa_ieee754_class TEXT NOT NULL,delta_tau_k_pa_ieee754_bits INTEGER NOT NULL,delta_tau_k_pa_ieee754_class TEXT NOT NULL,x_m_ieee754_bits INTEGER NOT NULL,x_m_ieee754_class TEXT NOT NULL,y_m_ieee754_bits INTEGER NOT NULL,y_m_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_placement (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1994_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,x REAL,y REAL,z REAL,yaw REAL,x_ieee754_bits INTEGER NOT NULL,x_ieee754_class TEXT NOT NULL,y_ieee754_bits INTEGER NOT NULL,y_ieee754_class TEXT NOT NULL,z_ieee754_bits INTEGER NOT NULL,z_ieee754_class TEXT NOT NULL,yaw_ieee754_bits INTEGER NOT NULL,yaw_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_stud (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1994_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,beam_id TEXT NOT NULL,x_m REAL,diameter_m REAL,height_m REAL,f_u_pa REAL,x_m_ieee754_bits INTEGER NOT NULL,x_m_ieee754_class TEXT NOT NULL,diameter_m_ieee754_bits INTEGER NOT NULL,diameter_m_ieee754_class TEXT NOT NULL,height_m_ieee754_bits INTEGER NOT NULL,height_m_ieee754_class TEXT NOT NULL,f_u_pa_ieee754_bits INTEGER NOT NULL,f_u_pa_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_case (id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES en1994_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,label_en TEXT NOT NULL,label_de TEXT NOT NULL,entry_id TEXT NOT NULL);
CREATE TABLE en1994_case_number (id INTEGER PRIMARY KEY,case_id INTEGER NOT NULL REFERENCES en1994_case(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,value REAL,value_ieee754_bits INTEGER NOT NULL,value_ieee754_class TEXT NOT NULL);
CREATE TABLE en1994_case_text (id INTEGER PRIMARY KEY,case_id INTEGER NOT NULL REFERENCES en1994_case(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),logical_id TEXT NOT NULL,value TEXT NOT NULL);
